def decode_base64_safely(s: str) -> str:

    s = s.strip()

    try:

        clean = re.sub(r"\s+", "", s)

        missing_padding = len(clean) % 4

        if missing_padding:

            clean += "=" * (4 - missing_padding)

        decoded = base64.b64decode(clean, validate=False).decode("utf-8", errors="ignore")

        if "proxies:" in decoded or "server:" in decoded or "://" in decoded:

            return decoded

    except Exception:

        pass

    return s





def sanitize_node(node: dict) -> dict:

    if not isinstance(node, dict):

        return None

    clean = {}

    for k, v in node.items():

        if k == "port":

            try:

                clean["port"] = int(v)

            except Exception:

                return None

        elif isinstance(v, (str, int, float, bool, list, dict)):

            clean[k] = v

    if not clean.get("server") or not clean.get("type") or not clean.get("port"):

        return None

    return clean





def extract_proxies_from_content(content: str) -> list:

    if not content:

        return []

    text = decode_base64_safely(content)

    text = re.sub(r"(short-id:\s*)([0-9a-fA-F]+)", r"\1'\2'", text)



    proxies = []

    # 1. Try pyyaml safe_load

    try:

        data = yaml.safe_load(text)

        if isinstance(data, dict) and "proxies" in data and isinstance(data["proxies"], list):

            for p in data["proxies"]:

                if isinstance(p, dict) and "server" in p and "port" in p and "type" in p:

                    proxies.append(p)

            if proxies:

                return proxies

        elif isinstance(data, list):

            for p in data:

                if isinstance(p, dict) and "server" in p and "port" in p and "type" in p:

                    proxies.append(p)

            if proxies:

                return proxies

    except Exception:

        pass



    # 2. Resilient Line-by-line block extractor fallback

    lines = text.splitlines()

    in_proxies = False

    cur_block = []



    def parse_block(b_lines):

        block_text = "\n".join(b_lines)

        try:

            parsed = yaml.safe_load(block_text)

            if isinstance(parsed, list) and len(parsed) > 0 and isinstance(parsed[0], dict):

                return parsed[0]

            if isinstance(parsed, dict):

                return parsed

        except Exception:

            pass

        item = {}

        for line in b_lines:

            m = re.match(r"^\s*-\s*([^:]+):\s*(.*)$", line)

            if not m:

                m = re.match(r"^\s*([^:]+):\s*(.*)$", line)

            if m:

                k = m.group(1).strip()

                v = m.group(2).strip().strip("'\"")

                if k == "port":

                    try: v = int(v)

                    except: pass

                item[k] = v

        if "server" in item and "port" in item and "type" in item:

            return item

        return None



    for line in lines:

        stripped = line.strip()

        if re.match(r"^proxies:\s*$", stripped):

            in_proxies = True

            continue

        if in_proxies and re.match(r"^(proxy-groups|rules|rule-providers|proxy-providers):\s*$", stripped):

            in_proxies = False

            if cur_block:

                p = parse_block(cur_block)

                if p: proxies.append(p)

                cur_block = []

            break

        if in_proxies:

            if re.match(r"^\s*-\s*", line):

                if cur_block:

                    p = parse_block(cur_block)

                    if p: proxies.append(p)

                    cur_block = []

                cur_block.append(line)

            elif cur_block:

                cur_block.append(line)



    if cur_block:

        p = parse_block(cur_block)

        if p: proxies.append(p)



    return proxies





def fetch_source_sync(url: str, max_retries: int = 3) -> str:

    headers = {

        "User-Agent": "ClashMeta/v1.19.2 (HerciniaCloud/2.0; +https://github.com/Alex234123/hercinia-node-pool)",

        "Accept": "*/*"

    }

    for attempt in range(max_retries):

        try:

            r = requests.get(url, headers=headers, verify=False, timeout=20)

            if r.status_code == 200 and len(r.content) > 50:

                return r.content.decode("utf-8", errors="ignore")

            elif r.status_code == 429:

                time.sleep(2 * (attempt + 1))

        except Exception:

            time.sleep(1)

    return ""





async def fetch_source_async(session: aiohttp.ClientSession, url: str) -> str:

    headers = {

        "User-Agent": "ClashMeta/v1.19.2 (HerciniaCloud/2.0; +https://github.com/Alex234123/hercinia-node-pool)",

        "Accept": "*/*"

    }

    for attempt in range(2):

        try:

            async with session.get(url, headers=headers, ssl=False, timeout=aiohttp.ClientTimeout(total=20)) as resp:

                if resp.status == 200:

                    text = await resp.text(errors="ignore")

                    if len(text) > 50:

                        return text

                elif resp.status == 429:

                    await asyncio.sleep(2)

        except Exception:

            await asyncio.sleep(1)

    return ""





def fetch_via_mihomo_core(sources: list) -> list:

    mihomo_bin = None

    for candidate in ["./mihomo", "mihomo", "/usr/local/bin/mihomo"]:

        if shutil.which(candidate) or (os.path.exists(candidate) and os.access(candidate, os.X_OK)):

            mihomo_bin = candidate

            break



    if not mihomo_bin:

        print("[Mihomo Engine] Core binary not found, skipping native proxy-provider extraction.")

        return []



    print(f"[Mihomo Engine] Found Mihomo core at '{mihomo_bin}', generating native proxy-provider configuration...")

    temp_dir = os.path.abspath("./temp_mihomo_run")

    os.makedirs(temp_dir, exist_ok=True)



    providers = {}

    for i, url in enumerate(sources):

        provider_name = f"sub_{i}"

        providers[provider_name] = {

            "type": "http",

            "url": url,

            "interval": 3600,

            "path": f"./{provider_name}.yaml",

            "health-check": {

                "enable": False

            }

        }



    config = {

        "port": 7890,

        "socks-port": 7891,

        "mode": "rule",

        "log-level": "info",

        "external-controller": "127.0.0.1:9097",

        "secret": "",

        "proxy-providers": providers

    }



    config_path = os.path.join(temp_dir, "config.yaml")

    with open(config_path, "w", encoding="utf-8") as f:

        yaml.dump(config, f, allow_unicode=True, sort_keys=False)



    print("[Mihomo Engine] Starting background Mihomo instance to trigger native subscription pull...")

    proc = subprocess.Popen(

        [mihomo_bin, "-d", temp_dir, "-f", config_path],

        stdout=subprocess.PIPE,

        stderr=subprocess.STDOUT

    )



    extracted_nodes = []

    try:

        api_ready = False

        for _ in range(24):

            time.sleep(0.5)

            try:

                r = requests.get("http://127.0.0.1:9097/providers/proxies", timeout=2)

                if r.status_code == 200:

                    api_ready = True

                    break

            except Exception:

                pass



        if api_ready:

            time.sleep(3)

            r = requests.get("http://127.0.0.1:9097/providers/proxies", timeout=5)

            if r.status_code == 200:

                prov_data = r.json().get("providers", {})

                for pname, pinfo in prov_data.items():

                    px_list = pinfo.get("proxies", [])

                    for p in px_list:

                        if isinstance(p, dict) and p.get("server") and p.get("port"):

                            clean = sanitize_node(p)

                            if clean:

                                extracted_nodes.append(clean)

                print(f"[Mihomo Engine] Successfully pulled {len(extracted_nodes)} raw nodes via Mihomo native core!")

        else:

            print("[Mihomo Engine] Timed out waiting for Mihomo external controller.")

    except Exception as e:

        print(f"[Mihomo Engine] Error querying Mihomo providers API: {e}")

    finally:

        try:

            proc.terminate()

            proc.wait(timeout=3)

        except Exception:

            try: proc.kill()

            except Exception: pass

        shutil.rmtree(temp_dir, ignore_errors=True)



    return extracted_nodes





def deduplicate_nodes(proxies: list) -> list:

    seen = set()

    unique = []

    for p in proxies:

        clean = sanitize_node(p)

        if not clean:

            continue

        server = str(clean.get("server", "")).strip().lower()

        port = str(clean.get("port", "")).strip()

        ptype = str(clean.get("type", "")).strip().lower()

        if not server or not port or not ptype:

            continue

        if server in ("127.0.0.1", "localhost", "0.0.0.0") or server.startswith("192.168."):

            continue

        

        raw_name = str(clean.get("name", "")).strip()

        clean_name = re.sub(r"[\s\-_\.:]+", "", raw_name).lower()

        secret = str(clean.get("uuid") or clean.get("password") or "")[:16]

        key = f"{ptype}|{server}:{port}|{secret}|{clean_name}"

        

        if key not in seen:

            seen.add(key)

            unique.append(clean)

    return unique





async def benchmark_node_tcp(node: dict, sem: asyncio.Semaphore, timeout: float = 2.0):
    async with sem:
        # UDP-based protocols (hysteria2, tuic, wireguard) skip TCP check
        ntype = str(node.get("type", "")).lower()
        if ntype in ["hysteria2", "hy2", "tuic", "wireguard"]:
            return (node, 66)

        server = str(node.get("server", "")).strip()
        try:
            port = int(node.get("port"))
        except Exception:
            return None

        t0 = time.perf_counter()
        try:
            reader, writer = await asyncio.wait_for(
                asyncio.open_connection(server, port),
                timeout=timeout
            )
            t1 = time.perf_counter()
            delay_ms = int((t1 - t0) * 1000)
            writer.close()
            try:
                await writer.wait_closed()
            except Exception:
                pass
            if 0 < delay_ms <= 2000:
                return (node, delay_ms)
        except Exception:
            pass
        return None


async def benchmark_node_real_mihomo(client: aiohttp.ClientSession, node_name: str, sem: asyncio.Semaphore, timeout: float = 3.0):
    async with sem:
        target_gen204 = "https://www.google.com/generate_204"
        test_url = f"http://127.0.0.1:9097/proxies/{urllib.parse.quote(node_name)}/delay?timeout=2500&url=" + target_gen204
        try:
            async with client.get(test_url, timeout=aiohttp.ClientTimeout(total=timeout)) as resp:
                if resp.status == 200:
                    data = await resp.json()
                    delay = data.get("delay", 0)
                    if 0 < delay < 2500:
                        return delay
        except Exception:
            pass
        return None


async def benchmark_all_nodes(nodes: list) -> list:
    print(f"[Benchmark: Stage 1] Pre-filtering {len(nodes)} candidate nodes via fast connectivity handshake...")
    sem_tcp = asyncio.Semaphore(150)
    tasks_tcp = [benchmark_node_tcp(n, sem_tcp, timeout=2.0) for n in nodes]
    results_tcp = await asyncio.gather(*tasks_tcp)
    tcp_alive = [r[0] for r in results_tcp if r is not None]
    print(f"[Benchmark: Stage 1] {len(tcp_alive)} nodes passed Stage 1 connectivity check.")

    if not tcp_alive:
        print("[Benchmark] No nodes passed Stage 1 check, fallback to original nodes.")
        return [(n, 66) for n in nodes]

    mihomo_bin = None
    for candidate in ["./mihomo", "mihomo", "/usr/local/bin/mihomo"]:
        if shutil.which(candidate) or (os.path.exists(candidate) and os.access(candidate, os.X_OK)):
            mihomo_bin = candidate
            break

    if not mihomo_bin:
        print("[Benchmark] No mihomo core detected. Gracefully falling back to Stage 1 alive nodes...")
        alive_fallback = [r for r in results_tcp if r is not None]
        alive_fallback.sort(key=lambda x: x[1])
        return alive_fallback

    print(f"[Benchmark: Stage 2] Testing REAL outbound connectivity via Mihomo Core for {len(tcp_alive)} nodes...")
    temp_dir = os.path.abspath("./.mihomo_bench_temp")
    os.makedirs(temp_dir, exist_ok=True)

    named_nodes = []
    for idx, n in enumerate(tcp_alive):
        node_copy = dict(n)
        node_copy["name"] = f"TestNode_{idx}"
        named_nodes.append(node_copy)

    temp_config = {
        "port": 7895,
        "socks-port": 7896,
        "mode": "rule",
        "log-level": "silent",
        "external-controller": "127.0.0.1:9097",
        "secret": "",
        "proxies": named_nodes
    }

    config_path = os.path.join(temp_dir, "config.yaml")
    with open(config_path, "w", encoding="utf-8") as f:
        yaml.dump(temp_config, f, allow_unicode=True)

    proc = subprocess.Popen([mihomo_bin, "-d", temp_dir, "-f", config_path], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    
    # Wait for Mihomo external controller ready
    for _ in range(20):
        await asyncio.sleep(0.3)
        try:
            r = requests.get("http://127.0.0.1:9097/version", timeout=1)
            if r.status_code == 200:
                break
        except Exception:
            pass

    real_alive = []
    try:
        sem_http = asyncio.Semaphore(60)
        async with aiohttp.ClientSession() as client:
            test_tasks = [
                benchmark_node_real_mihomo(client, n["name"], sem_http)
                for n in named_nodes
            ]
            delays = await asyncio.gather(*test_tasks)

            for original_n, delay in zip(tcp_alive, delays):
                if delay:
                    real_alive.append((original_n, delay))
    except Exception as e:
        print(f"[Benchmark: Stage 2] Mihomo benchmark encountered notice: {e}")
    finally:
        try:
            proc.terminate()
            proc.wait(timeout=3)
        except Exception:
            try: proc.kill()
            except Exception: pass
        shutil.rmtree(temp_dir, ignore_errors=True)

    if real_alive:
        real_alive.sort(key=lambda x: x[1])
        print(f"[Benchmark] Completed! {len(real_alive)} out of {len(nodes)} nodes verified 100% REAL OUTBOUND ALIVE (HTTP 204)!")
        return real_alive
    else:
        print("[Benchmark: Stage 2] No real outbound ping passed (or test target blocked in CI). Falling back to Stage 1 alive nodes!")
        alive_fallback = [r for r in results_tcp if r is not None]
        alive_fallback.sort(key=lambda x: x[1])
        return alive_fallback



